const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/coordination_issues/export',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    'filters[assignee_company_id][]': 'SOME_ARRAY_VALUE',
    'filters[created_by_company_id][]': 'SOME_ARRAY_VALUE',
    column_state: 'SOME_ARRAY_VALUE',
    'filters[assignee_id][]': 'SOME_ARRAY_VALUE',
    'filters[ids][]': 'SOME_ARRAY_VALUE',
    'filters[location_id][]': 'SOME_ARRAY_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    'filters[coordination_issue_file_id][]': 'SOME_ARRAY_VALUE',
    'filters[status][]': 'SOME_ARRAY_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[issue_type][]': 'SOME_ARRAY_VALUE',
    'filters[priority][]': 'SOME_ARRAY_VALUE',
    'filters[trade_id][]': 'SOME_ARRAY_VALUE',
    'filters[overdue]': 'SOME_BOOLEAN_VALUE',
    view: 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE',
    export_format: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/coordination_issues/export?project_id=SOME_INTEGER_VALUE&filters%5Bassignee_company_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bcreated_by_company_id%5D%5B%5D=SOME_ARRAY_VALUE&column_state=SOME_ARRAY_VALUE&filters%5Bassignee_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bids%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Blocation_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&filters%5Bcoordination_issue_file_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bstatus%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Bissue_type%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Bpriority%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Btrade_id%5D%5B%5D=SOME_ARRAY_VALUE&filters%5Boverdue%5D=SOME_BOOLEAN_VALUE&view=SOME_STRING_VALUE&sort=SOME_STRING_VALUE&export_format=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
